"""Generates docs/FORMAT-MATRIX.md from the engines' testdata/<engine>/matrix-results.json files.
Run:  python -I tools/gen_matrix.py
Only entries that a test actually produced are listed; nothing is added by hand."""
import json, os, datetime, collections

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
engines = [("image", "Images"), ("media", "Video and audio"), ("pdf", "PDF"), ("doc", "Documents, presentations, spreadsheets, subtitles"), ("archive", "Archives"), ("meta", "Metadata")]
lines = ["# Format matrix", "",
         "Generated by `tools/gen_matrix.py` from `testdata/<engine>/matrix-results.json`. Each row is a conversion path that a test",
         "ran end to end on a real file and checked with an independent reader. A path that is not listed is **not claimed**.",
         "Rows whose id has no `>` are other engine checks (kept so the evidence is visible).", ""]
total = collections.Counter()
for key, title in engines:
    p = os.path.join(root, "testdata", key, "matrix-results.json")
    if not os.path.exists(p):
        lines += [f"## {title}", "", "_No results file yet._", ""]
        continue
    j = json.load(open(p, encoding="utf-8"))
    res = j.get("results", {})
    stamp = datetime.datetime.fromtimestamp(os.path.getmtime(p)).strftime("%Y-%m-%d %H:%M")
    c = collections.Counter(v.get("status", "?") for v in res.values())
    total.update(c)
    extra = f", LibreOffice {j['libreoffice']}" if j.get("libreoffice") else ""
    lines += [f"## {title}", "", f"{len(res)} entries ({', '.join(f'{n} {s}' for s, n in sorted(c.items()))}); results file written {stamp}{extra}.", ""]
    paths = {k: v for k, v in res.items() if ">" in k}
    other = {k: v for k, v in res.items() if ">" not in k}
    if paths:
        by_in = collections.defaultdict(list)
        for k, v in sorted(paths.items()):
            i, o = k.split(">", 1)
            by_in[i].append((o, v))
        lines += ["| From | To (all verified unless marked) |", "|---|---|"]
        for i, outs in sorted(by_in.items()):
            cells = ", ".join(o if v.get("status") == "pass" else f"{o} ({v.get('status')})" for o, v in outs)
            lines.append(f"| {i} | {cells} |")
        lines.append("")
        notes = collections.OrderedDict()
        for k, v in sorted(paths.items()):
            n = v.get("note", "")
            if n and n != "ok" and not n.startswith("ok;") and "verified" not in n[:9]:
                notes[k] = n
            elif n.startswith("ok;"):
                notes[k] = n[4:]
        if notes:
            lines += ["<details><summary>Per-path notes and warnings</summary>", ""]
            lines += [f"- `{k}`: {n}" for k, n in notes.items()]
            lines += ["", "</details>", ""]
    if other:
        lines += ["| Check | Result |", "|---|---|"]
        lines += [f"| `{k}` | {v.get('status')} - {v.get('note','')} |" for k, v in sorted(other.items())]
        lines.append("")
mp = os.path.join(root, "testdata", "doc", "manual-checks.json")
if os.path.exists(mp):
    mj = json.load(open(mp, encoding="utf-8")).get("results", {})
    lines += ["## Manual checks (run by hand with `filo-cli`, then recorded in `testdata/doc/manual-checks.json`)", "",
              "These paths are registered and ran on real fixtures; they are not yet covered by the automated matrix. Structural checks only (zip valid, XML well-formed, text present) - the files were not opened in Office.", "",
              "| Path | Result | Note |", "|---|---|---|"]
    lines += [f"| `{k}` | {v.get('status')} | {v.get('note','')} |" for k, v in sorted(mj.items())]
    lines.append("")
lines += ["## Not supported (by design, see KNOWN-LIMITATIONS.md)", "",
          "- **Pages (`.pages`) as an output**: Apple's format is not documented; Filo only reads the preview PDF stored inside a `.pages` file.",
          "- Any conversion not listed above or in the manual checks.", "",
          f"Totals across all results files: {', '.join(f'{n} {s}' for s, n in sorted(total.items()))}.", ""]
open(os.path.join(root, "docs", "FORMAT-MATRIX.md"), "w", encoding="utf-8").write("\n".join(lines))
print("wrote docs/FORMAT-MATRIX.md", dict(total))
